const ruc = "20" + String(Math.floor(Math.random() * 1e9)).padStart(9, "0");
pm.request.body.update(JSON.stringify({
  businessName: "Cliente inexistente SAC",
  ruc: ruc,
  representative: "Ana Torres",
  email: "inexistente@correo.pe",
  phone: "987654321",
  address: "Av. Arequipa 123, Lima"
}));

pm.test("Status 200", () => pm.response.to.have.status(200));
const plans = pm.response.json();
pm.collectionVariables.set("planSeedId", plans[0].id);

